    const latestReceived = await f.db.healthFollowupRecord.findFirstOrThrow({ where: { receiverId: riraBinding.receiverId, originId: riraRequestTwo.id } });
    assert.equal((latestReceived.payload as { data: { status: string } }).data.status, "DEVOLVIDA");
    assert.equal(await f.db.healthFollowupRecord.count({ where: { receiverId: riraBinding.receiverId } }), 3);
