    await f.db.healthWaitlist.createMany({ data: Array.from({ length: 501 }, (_, index) => ({ id: `followup-bulk-wait-${index}`, patientId: "followup-bulk-patient", unitId: "followup-bulk-unit", createdByUsuarioId: context.user.id, status: "Aguardando", priority: "Normal" })) });
    const bulkBinding = await configureHealthFollowup(context, { unitId: "followup-bulk-unit", contract: "CELERIFLOW_RIRA", code: "RIRA_BULK_UNIT", name: "Receptor das origens de lote completo" });
    const bulkBatches = await generateHealthFollowupBatches(context, { bindingId: bulkBinding.id, requestKey: randomUUID(), fromDate: "2000-01-01", toDate: dateText(0) });
